import { readFile, writeFile } from "node:fs/promises";
const directory = new URL("../google-apps-script/", import.meta.url);
const [sync, login] = await Promise.all([
  readFile(new URL("Code.gs", directory), "utf8"),
  readFile(new URL("GoogleLogin.gs", directory), "utf8"),
]);
await writeFile(
  new URL("INSTALL.gs.txt", directory),
  "// Generated by scripts/package-google-login.mjs. Paste this WHOLE file into Code.gs.\n" +
    sync +
    "\n" +
    login,
  "utf8",
);
process.stdout.write(
  "Prepared google-apps-script/INSTALL.gs.txt (no credentials included).\n",
);
